<?php $title='Live RFID Attendance'; require_once __DIR__.'/../partials/header.php'; ?><section class="grid stats"><div class="card"><div class="muted">Active Employees</div><div class="metric" id="total">0</div></div><div class="card"><div class="muted">Present Today</div><div class="metric" id="present">0</div></div><div class="card"><div class="muted">Absent Today</div><div class="metric" id="absent">0</div></div><div class="card"><div class="muted">Kiosk</div><div class="metric" style="font-size:20px" id="status">Checking…</div></div></section><section class="panel"><div class="panel-head"><h2>Live Punch Stream</h2><a class="btn btn-primary" href="../kiosk/" target="_blank">Open Kiosk</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Employee</th><th>Department</th><th>Action</th><th>Event</th></tr></thead><tbody id="rows"><tr><td colspan="5" class="empty">Loading…</td></tr></tbody></table></div></section><script>const api='../api/index.php?resource=live&limit=50';async function load(){try{const r=await fetch(api,{cache:'no-store'});if(!r.ok)throw 0;const d=await r.json();document.getElementById('total').textContent=d.stats.total_active;document.getElementById('present').textContent=d.stats.present;document.getElementById('absent').textContent=d.stats.absent;document.getElementById('status').textContent='ONLINE';document.getElementById('rows').innerHTML=d.punches.map(x=>`<tr><td>${x.punched_at}</td><td><strong>${x.employee_code}</strong> — ${x.name}</td><td>${x.department}</td><td><span class="badge ${x.punch_type==='IN'?'present':'late'}">${x.punch_type}</span></td><td><code>${x.event_id}</code></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No punches yet.</td></tr>';}catch(e){document.getElementById('status').textContent='OFFLINE';}}load();setInterval(load,2000);</script><?php require_once __DIR__.'/../partials/footer.php'; ?>
